INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'El MRR – Ingresos Pasivos que se Construyen Mes a Mes', 'El 3% MRR se paga mensualmente durante 12 meses sobre las licencias activas de cada cliente que el Hunter trajo. Cada cliente que trae le paga mes a mes, construyendo una "cola" de ingresos que se acumula. Después de un año con 10 clientes, el Hunter recibe el 3% de las licencias de esos 10 clientes mensualmente sin hacer nada adicional. El MRR es el sueño del vendedor: ingresos que llegan sin esfuerzo adicional.', 'Un Hunter cierra 2 clientes al mes durante 6 meses = 12 clientes. Cada cliente paga un promedio de S/700/mes en licencias. El 3% de S/700 es S/21/mes por cliente. Después de 6 meses, el Hunter tiene una cola MRR de 12 clientes × S/21 = S/252/mes. Al año, con 24 clientes, la cola MRR es S/504/mes. Ese dinero llega mes a mes sin esfuerzo adicional.', NULL, NULL, NULL, 1);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'Los Bonos – Gasolina Extra para el Esfuerzo', 'Bonos escalonados: Bono de Inicio S/408 (3 ventas en primer mes), Ejecutivo Ideal S/850 (5 ventas/mes), Top Performer S/1,020 (7 ventas/mes), Bono Trimestral S/3,400 (promedio 10 ventas/mes). Los bonos transforman un buen mes en un mes excepcional y recompensan la consistencia. Son la gasolina que impulsa al Hunter a ir más allá de la meta mínima.', 'Un Hunter tiene un mes con 7 ventas. Base: S/2,958. Comisiones: S/980. Bono: S/1,020. Total: S/4,958. Si mantiene 10 ventas/mes en el trimestre, gana S/3,400 adicionales. La diferencia entre 5 y 7 ventas es S/170 de bono extra; entre 7 y 10, el bono trimestral de S/3,400. El esfuerzo adicional se paga solo.', NULL, NULL, NULL, 2);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', '"Venta Grande Vale por Tres" – Apunta a lo Grande', 'Si el Hunter cierra una venta cuyo setup facturado suma S/15,000 o más (ej. una cadena de varias sedes), esa venta cuenta como 3 para la escalera base. Esto reconoce que cerrar una cuenta grande requiere tanto o más esfuerzo que cerrar tres pequeñas, y alinea el incentivo del Hunter con el valor del negocio. Una venta grande puede catapultar el ingreso del Hunter en un solo mes.', 'Un Hunter cierra una cadena de 5 sedes con un setup de S/18,000. Aunque es una sola transacción, cuenta como 3 ventas para la escalera base. El Hunter recibe la base completa de S/2,958 en su liquidación, más las comisiones de setup desde la primera venta (10% de S/18,000 = S/1,800). En una sola transacción, el Hunter gana más que en 3 transacciones pequeñas.', NULL, NULL, NULL, 3);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'El Bono Trimestral – La Recompensa a la Consistencia', 'El Bono Trimestral de S/3,400 se otorga cuando el Hunter mantiene un promedio de 10 ventas/mes (o 30 en el trimestre). No es un bono por un mes bueno; es un bono por consistencia. Esto incentiva al Hunter a no bajar el ritmo y a mantener su pipeline lleno durante todo el trimestre. La consistencia es la clave para escalar al nivel Elite.', 'Un Hunter tiene un trimestre con 10, 9 y 11 ventas. Promedio: 10 ventas/mes. Gana el bono de S/3,400, que se suma a su base y comisiones. Ese mes extra de S/3,400 puede representar el 40-50% de su ingreso mensual. La consistencia no solo genera ingresos estables, sino que tiene una recompensa extraordinaria.', NULL, NULL, NULL, 4);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'La Comparación con Números – El Argumento del Ahorro', 'El Hunter debe comparar INVU con las alternativas del mercado peruano con datos concretos. Sumar el costo del PSE externo, el soporte aparte y las horas de configuración que la competencia no incluye. Mostrar que INVU (S/350/mes todo incluido) es más barato que la competencia (S/450/mes con PSE y soporte). La diferencia de S/100 es el 0.2% de la facturación de un restaurante de S/50,000. Los números son el arma más poderosa del Hunter.', '"Los sistemas básicos te cobran S/250 de licencia POS, pero aparte te cobran S/120 de PSE externo y S/80 de soporte. Suma S/450 mensuales. INVU: S/350 mensuales todo incluido. Además, la competencia no tiene KDS, ni ecommerce, ni fidelización integrada. Cuando necesites esas herramientas, tendrás que comprar sistemas separados. INVU ya las tiene. Esa diferencia de S/100 al mes es el 0.2% de tu facturación."', NULL, NULL, NULL, 5);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'La Objeción "Es Caro" – El Protocolo Gravity en Acción', 'Toda objeción es una oportunidad para construir valor. El Protocolo Gravity para "es caro" tiene 5 pasos: Validar (entiendo que el precio es importante), Diagnosticar (¿qué te parece caro exactamente?), Reencuadrar (cuando sumas el PSE, el costo real es mayor), Micro-cierre (¿te parece si hacemos el cálculo con tus números?), y Cierre (¿qué día te acomoda para la demo?). Este protocolo convierte la objeción en una oportunidad de cierre.', 'Cliente: "Es caro."  
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'La Objeción "Ya Tengo un POS" – Diagnosticar el Dolor Oculto', 'El cliente que dice "ya tengo un POS" no está cerrado; está diciendo que no ve razón para cambiar. El Hunter debe diagnosticar qué le falta a su sistema actual. Preguntas: "¿Tu sistema actual incluye facturación electrónica nativa o pagas aparte? ¿Puedes centralizar varias sedes desde un solo panel? ¿Tienes control de inventario en tiempo real?" Si no tiene esas funcionalidades, INVU es una mejora, no un cambio. El dolor oculto es la llave para abrir la venta.', '"Me alegra que tengas un sistema. ¿Tu sistema actual incluye facturación electrónica nativa o pagas aparte? ¿Puedes centralizar varias sedes desde un solo panel? ¿Tienes control de inventario en tiempo real? ¿Tienes e-commerce propio sin comisiones? INVU hace todo eso en un solo sistema. No se trata de cambiar por cambiar. Se trata de tener una operación rentable."', NULL, NULL, NULL, 7);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'La Objeción "Lo Voy a Pensar" – El Costo de la Postergación', 'El cliente que dice "lo voy a pensar" está en el momento de indecisión. El Hunter debe validar que es normal, educar sobre el costo de postergar (tiempo, dinero, oportunidades perdidas), comparar cada mes sin integración con la inversión, y cerrar ofreciendo una demo sin compromiso. El costo de postergar es el argumento que mueve al cliente a actuar.', '"Es normal. Lo que muchos clientes me dicen es que después de pensar, se dan cuenta de que el costo de no tener control es mayor que la inversión. Cada mes que postergas, estás pagando S/120 a Nubefact, perdiendo S/2,000 en mermas y S/2,500 en comisiones de delivery. Pensarlo cuesta dinero. ¿Qué información te falta para decidir? Si es algo que puedo resolver hoy, lo resolvemos."', NULL, NULL, NULL, 8);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'El Setup – Inversión, No Gasto', 'El setup de INVU es un desembolso inicial que muchos clientes ven como un gasto. El Hunter debe reencuadrarlo como una inversión que ahorra meses de operación rota. La competencia no cobra setup porque no hace nada: da el software y el cliente lo configura. INVU cobra setup porque deja el restaurante operando desde el día uno. El setup es inversión, no gasto. Esta reencuadre cambia la percepción del cliente.', '"Entiendo que el setup es un desembolso inicial importante. Ese setup lo pagás una vez y te ahorra meses de operación rota. Además te lo podemos plantear como facturación anual con mejor precio. La competencia no cobra setup porque no hace nada: te dan el software y tú lo configuras. INVU te deja el restaurante operando desde el día uno. El setup es inversión, no gasto."', NULL, NULL, NULL, 9);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'El Registro en CRM – Lo que no está, no existe', 'El registro en CRM es la disciplina que separa al Hunter profesional del aficionado. Cada visita, reunión, demo y oportunidad debe estar registrada. Los viáticos se pagan solo con evidencia de gestiones. El CRM es la herramienta que convierte el esfuerzo en resultado y permite a la empresa apoyar al Hunter con datos reales. Lo que no está en CRM, no existe. Esta es la regla de oro del Hunter.', 'Un Hunter hace 15 visitas a la semana, pero no las registra. Al final del mes, no puede demostrar su esfuerzo para recibir viáticos. Además, pierde seguimiento de oportunidades porque no las anotó. Otro Hunter registra cada visita, cada reunión y cada promesa en el CRM. La empresa ve su esfuerzo, le paga sus viáticos, y le da seguimiento a sus oportunidades. El Hunter que registra, triunfa.', NULL, NULL, NULL, 10);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'El Caso del Restaurante con Facturación Externa y Múltiples Sedes – El Cliente Ideal', 'Un cliente con 3 sedes que paga Nubefact aparte y no tiene control centralizado es el cliente ideal para INVU. El Hunter debe mostrar que el costo actual (S/1,110/mes) es solo un poco menor que INVU (S/1,862/mes), pero que INVU incluye centralización, FE nativa, KDS y Loyalty. El ahorro en mermas (2% = S/2,400/mes) y comisiones de delivery cubren la diferencia. Este caso es el ejemplo perfecto para demostrar el ROI de INVU.', '"Entiendo que el costo de INVU es mayor que lo que pagas hoy. Hoy pagas S/1,110 mensuales: S/750 por los 3 POS y S/360 por Nubefact. Con INVU, el costo mensual es S/1,862, que incluye centralización, FE nativa, KDS y Loyalty. La diferencia es S/752, que es el 0.6% de tu facturación mensual. Pero lo que no estás viendo es lo que te cuesta no tener centralización: precios desactualizados, inventario que no cuadra, mermas sin control. Si reducimos tus mermas en un 2%, son S/2,400 mensuales de ahorro. La inversión se paga sola."', NULL, NULL, NULL, 11);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'Los Errores que Matan la Venta – Lo que el Hunter Debe Evitar', 'Hay 6 errores comunes que el Hunter debe evitar: Hablar de precio antes de diagnosticar; hacer una demo genérica sin enfocarse en el dolor; no sumar los costos ocultos de la competencia; no comparar con la competencia local; no cerrar con una pregunta de avance; hacer descuentos sin justificación. Estos errores convierten al vendedor en un "proveedor más" y lo sacan de la categoría de "asesor de confianza". Evitarlos es el primer paso para ser un Hunter Elite.', 'Un cliente pregunta: "¿Cuánto cuesta?"  
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'Los Niveles de Dominio – De Básico a Gravedad Cero', 'El Hunter pasa por 4 niveles: Básico (explica el producto sin conectar beneficios), Medio (conecta beneficios y diagnostica), Alto (justifica el precio y maneja objeciones con autoridad), y Gravedad Cero (controla la conversación y cierra con autoridad, sin descuentos). El objetivo es llegar a Gravedad Cero: ser un asesor estratégico del restaurantero, no un vendedor más. Cada nivel es un escalón que el Hunter debe subir con disciplina y práctica.', 'Básico: "INVU tiene facturación electrónica nativa."  
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'El Potencial de Ingresos del Hunter – Sin Techos, Sin Límites', 'El Hunter tiene un potencial de ingresos ilimitado. Desde S/35,496 anuales (3 ventas/mes) hasta más de S/100,000 anuales (Hunter Elite con cuentas grandes). El ingreso está directamente ligado al esfuerzo y la consistencia. No hay techos artificiales; el cielo es el límite. Cada venta adicional es puro ingreso incremental. El Hunter que entiende esto, se motiva a dar siempre un paso más.', '3 ventas/mes: S/35,496 anuales.  
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'El Valor del Onboarding Consultivo para el Hunter', 'El onboarding consultivo de INVU es un diferenciador clave que el Hunter debe comunicar. INVU no solo enseña a usar el sistema; ayuda al cliente a montar una operación rentable: menú con recetas costeadas, materia prima, proveedores, márgenes reales por plato. Muchos dueños operan a ciegas: no saben cuánto ganan por plato, no controlan mermas. El onboarding consultivo transforma al vendedor en un asesor de confianza y es un argumento de cierre poderoso.', '"No solo te enseñamos a usar el sistema. Te ayudamos a montar tu operación para que sea rentable desde el día uno. Seteamos tu menú con recetas y costos reales, tu materia prima y proveedores. Así, cuando vendas un plato, sabes exactamente cuánto estás ganando. No más operar a ciegas." El dueño, que nunca ha visto el margen real de sus platos, percibe a INVU como un socio, no como un proveedor.', NULL, NULL, NULL, 15);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'Soporte Local 24/7 – El Seguro de Continuidad para el Cliente', 'INVU tiene equipo de soporte en Perú, con WhatsApp directo a un humano, soporte remoto y en sitio. La competencia tiene tickets de 24-48 horas y soporte desde otro país. Cuando el sistema falla un viernes a las 9pm, el cliente llama a un equipo en Perú que responde en minutos. El Hunter debe vender esto como tranquilidad operativa. Es un argumento que la competencia no puede igualar.', 'Un cliente objeta: "¿Y si el sistema falla un viernes a las 9pm?" El Hunter responde: "Excelente pregunta. Con INVU, llamas a nuestro equipo en Perú, por WhatsApp, y te responde un humano. No bots, no formularios, no espera de 48 horas. La competencia te da un ticket que responden en 24-48 horas desde otro país. INVU te da un humano que habla tu idioma." El cliente se siente seguro.', NULL, NULL, NULL, 16);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'Ecosistema Móvil Nativo – El Negocio en el Bolsillo del Dueño', 'INVU ofrece tres apps nativas: POS para operar, Reports para medir desde cualquier lugar, y Supply para inventario y compras desde el móvil. La competencia encadena al usuario a una sola pantalla fija. El Hunter debe comunicar que INVU libera al dueño de la obligación de estar presente para controlar su negocio. Es el sueño del emprendedor: control total desde la palma de la mano.', '"Con INVU, tu negocio vive donde vos estés. Operás desde cualquier dispositivo con INVU POS, medís tus ventas y movimientos con INVU Reports desde tu celular, y gestionás compras e inventario con INVU Supply. No estás encadenado a una caja fija. Puedes estar en casa o de viaje y saber exactamente cómo va tu operación."', NULL, NULL, NULL, 17);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'Ecosistema Integrado sin Comisiones – El 100% es para Ti', 'INVU integra POS, KDS, inventario, QR, kioskos, loyalty y e-commerce en una sola plataforma, con e-commerce propio sin comisiones por venta. La competencia cobra comisiones de 25-30% por delivery. El Hunter debe mostrar que INVU permite vender sin ceder margen a terceros, lo que multiplica la rentabilidad del cliente. Es una propuesta de valor que la competencia no puede ofrecer.', '"No necesitas cinco sistemas diferentes. INVU integra POS, inventario, facturación, QR, kioskos, loyalty y e-commerce en una sola plataforma. Y tu tienda online no paga comisiones: el 100% de la venta es para ti. Un solo sistema, un solo costo, cero comisiones. Lo que antes perdías en Rappi, ahora lo ganas."', NULL, NULL, NULL, 18);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'El KPI del Hunter – De Discovery a Cotización', 'El KPI principal del Hunter no es cuántas demos se hacen, sino cuántos clientes pasan de discovery a cotización. Ahí está la conversión real. El Hunter debe enfocar sus esfuerzos en calificar oportunidades y avanzarlas en el pipeline. Una demo sin cotización es una oportunidad perdida. El objetivo es convertir cada oportunidad calificada en una cotización y cada cotización en un cierre.', 'Un Hunter hace 5 demos al mes, pero solo convierte 2 en cotizaciones. Su tasa de conversión es del 40%. Otro Hunter hace 5 demos y convierte 4 en cotizaciones (80%). Su ingreso es el doble. El KPI es la conversión, no la actividad. El Hunter debe enfocarse en calificar mejor y avanzar más rápido las oportunidades.', NULL, NULL, NULL, 19);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'La Visita Técnica – No es un Trámite, es una Herramienta de Ventas', 'La visita técnica en INVU POS no es un simple trámite de instalación. Es una herramienta estratégica de consultoría que se sitúa entre la validación comercial inicial y la cotización definitiva, permitiendo al Hunter demostrar profesionalismo, identificar necesidades adicionales de hardware y garantizar una implementación exitosa desde el día uno. El Hunter que entiende esto no ve la visita como una obligación, sino como una oportunidad de cerrar con autoridad.', 'Un Hunter ha cerrado la demo y el cliente está interesado, pero duda por el precio. El Hunter dice: "Antes de darte la cotización definitiva, nuestro especialista técnico va a evaluar tu local sin costo. Te va a decir qué hardware puedes reutilizar y qué necesitas para que tu operación funcione sin interrupciones. Con ese informe, te doy una cotización precisa y te aseguro que desde el día uno estarás operando." El cliente, que ve profesionalismo, acepta la visita y el Hunter usa el informe para cerrar.', NULL, NULL, NULL, 20);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'La Visita Técnica como Auditoría Operativa Integral', 'La visita técnica es una auditoría operativa integral que evalúa tres dimensiones críticas: conectividad (velocidad de internet, estabilidad del enlace, cobertura WiFi), equipamiento (impresoras, balanzas, cajones, lectores), y red de trabajo (topologías de red local, ruteo de cables, ubicación de estaciones). No es una inspección superficial; es una evaluación profunda que garantiza que el sistema funcionará desde el día uno.', 'El especialista de INVU llega al local del cliente. No solo mira la impresora; la prueba, mide la velocidad del internet, camina por todo el local con un medidor de WiFi, revisa los cables, y evalúa dónde debería ir la caja y la pantalla KDS. Al final, entrega un informe detallado. El cliente queda impresionado porque nunca nadie había hecho una evaluación tan completa. La confianza en INVU se multiplica.', NULL, NULL, NULL, 21);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'La Visita Técnica – Consultoría Gratuita, no Inspección de Control', 'INVU no envía a un técnico a revisar si el cliente cumple requisitos para negarle el servicio. Envía un especialista para asegurar que la implementación sea 100% exitosa y para hacer recomendaciones personalizadas según el flujo de operación del negocio. El Hunter debe comunicar esto como un valor agregado, no como una inspección.', 'Un cliente dice: "¿Van a venir a revisar mi local para ver si cumplo con requisitos?" El Hunter responde: "No es una inspección. Es una consultoría gratuita. Nuestro especialista viene a asegurarse de que tu implementación sea exitosa. Te va a recomendar qué hardware puedes reutilizar y qué mejoras te van a ayudar a operar sin problemas. No es para negarte el servicio; es para que funcione perfectamente desde el día uno."', NULL, NULL, NULL, 22);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'Reutilización de Hardware – Confianza y Ahorro para el Cliente', 'A diferencia de muchos POS que obligan al cliente a comprar todo el hardware nuevo, INVU evalúa lo que el cliente ya tiene y recomienda reutilizar todo lo que sea compatible (impresoras, lectores, cajones). Esto ahorra dinero al cliente y construye confianza. El Hunter debe comunicar esto como un gesto de honestidad, no como una concesión.', 'El cliente dice: "No quiero comprar impresoras nuevas." El Hunter responde: "No vamos a obligarte a comprar hardware nuevo si lo que tienes funciona. Nuestro especialista va a revisar tus impresoras, lectores y cajones, y te va a recomendar reutilizar todo lo que sea compatible. Así ahorras en la inversión inicial y solo compras lo que realmente necesitas." El cliente confía en el vendedor porque no le está vendiendo algo que no necesita.', NULL, NULL, NULL, 23);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'La Evaluación de Conectividad – El Combustible del Sistema', 'El internet es el combustible de INVU POS. Si la red falla, el sistema no opera, las ventas se pierden y el cliente se frustra. El especialista técnico evalúa la velocidad del internet contratado, la estabilidad del enlace de datos, y mapea la cobertura WiFi del recinto comercial, identificando puntos muertos. El Hunter debe comunicar que esta evaluación es esencial para la continuidad del negocio.', '"La velocidad es solo una parte. También evaluamos la estabilidad, la latencia, y la cobertura WiFi en toda el área del local. A veces el internet es rápido pero la señal no llega a la cocina, o se cae en horas pico. Nuestro especialista va a medir todo eso para asegurarse de que no tengas puntos ciegos." El cliente, que ha tenido caídas en horas pico, valora la evaluación.', NULL, NULL, NULL, 24);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'Fibra Óptica vs. Coaxial – La Diferencia que Afecta la Operación', 'INVU recomienda fibra óptica (FTTH) para estabilidad y baja latencia. Coaxial (HFC) genera latencia inestable y no es recomendado para operaciones de alta demanda. El Hunter debe saber esto para recomendar la mejora si el cliente tiene coaxial. Esta recomendación puede evitar problemas críticos en la operación.', 'Durante la visita, el especialista detecta que el cliente tiene internet coaxial. Le explica: "El coaxial es inestable y puede generar latencia en horas pico, lo que afectaría tu sistema y tus integraciones con delivery. Te recomendamos migrar a fibra óptica para garantizar estabilidad. Es una inversión que te ahorrará dolores de cabeza." El cliente, que no sabía la diferencia, valora la recomendación profesional.', NULL, NULL, NULL, 25);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'El Router 4G/5G de Respaldo – El Seguro de Continuidad', 'Para comercios con alta demanda de delivery e integraciones, INVU recomienda instalar un router con chip 4G/5G de contingencia automática que asegura operación continua si el internet principal falla. El Hunter debe vender esto como un seguro, no como un lujo. Es la garantía de que el negocio nunca se detiene.', '"Tu internet puede fallar, pero tu negocio no debe detenerse. Por eso recomendamos un router con chip 4G de respaldo. Si el internet principal se cae, el sistema cambia automáticamente al respaldo y sigues operando sin perder una venta. Es tu seguro de continuidad." El cliente, que ha perdido ventas por cortes de internet, ve el valor inmediato y acepta la recomendación.', NULL, NULL, NULL, 26);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'El Hardware Homologado – Impresora 3nStar RPT004', 'INVU recomienda la impresora 3nStar RPT004 como hardware oficial por su altísima resistencia térmica y doble interfaz (USB/LAN), garantizando durabilidad y compatibilidad. Una impresora que se traba genera caos en la operación. El Hunter debe comunicar que el hardware homologado es una inversión en estabilidad, no un gasto.', '"Recomendamos la impresora 3nStar RPT004 porque es la que hemos probado y validado para funcionar perfectamente con INVU. Es resistente, rápida y tiene doble conexión USB/LAN, así que no se desconecta. Es una inversión que te ahorrará dolores de cabeza a largo plazo." El cliente, que ha sufrido con impresoras que se traban, aprecia la recomendación.', NULL, NULL, NULL, 27);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'Evaluación de Topología de Red – La Eficiencia Operativa', 'INVU no solo instala el software en cualquier lugar. Diseña la distribución de los equipos para maximizar la eficiencia operativa: dónde va la caja, dónde va la impresora de comandas, dónde va la pantalla KDS en cocina. Una mala ubicación genera cuellos de botella. El Hunter debe comunicar que la visita técnica optimiza el flujo de trabajo.', '"No solo instalamos el sistema en cualquier lugar. Nuestro especialista diseña la ubicación de cada equipo para que tu operación sea lo más eficiente posible: la caja en el lugar correcto, la impresora de comandas donde la cocina la vea rápido, la pantalla KDS donde el cocinero la tenga a la vista. Así tu personal trabaja más rápido y tus clientes esperan menos."', NULL, NULL, NULL, 28);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'El Sistema Mesh WiFi – El Fin de los Puntos Muertos', 'Cuando la cobertura WiFi no llega a toda el área del local (especialmente a la cocina o al fondo del restaurante), el especialista recomienda sistemas de red en malla (Mesh WiFi) para eliminar puntos muertos. El Hunter debe comunicar que esto garantiza que el sistema funcione en todo el local, sin interrupciones.', 'Durante la visita, el especialista detecta que la señal WiFi no llega a la cocina. Le dice al dueño: "Tu cocina está en un punto muerto. Los pedidos pueden no llegar a tiempo. Te recomendamos un sistema Mesh WiFi para que la señal llegue a todo el local. Es una inversión pequeña que garantiza que tu operación fluya sin interrupciones."', NULL, NULL, NULL, 29);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'El Upselling durante la Visita Técnica – +40% de Ticket Promedio', 'Según datos históricos de INVU, la visita técnica genera un +40% de aumento en el ticket medio al identificar necesidades adicionales de hardware que el cliente no había considerado: tablets nuevas, impresoras adicionales, routers mejorados, sistemas Mesh, hardware de respaldo. El Hunter que domina la visita técnica convierte cada visita en una oportunidad de upselling.', 'Un Hunter agenda la visita técnica para un restaurante. El especialista descubre que el WiFi no llega a la cocina, que la impresora es obsoleta, y que el internet es coaxial. El informe recomienda: router Mesh WiFi, impresora 3nStar RPT004, y migración a fibra óptica. El Hunter incluye esto en la cotización, sumando S/1,500 en hardware adicional. Su comisión (10% desde la 4ª venta) aumenta en S/150. El cliente tiene certeza de que el sistema funcionará sin problemas.', NULL, NULL, NULL, 30);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'La Reducción de Tickets de Soporte – El Beneficio Oculto', 'Al validar técnicamente el local antes de la instalación, INVU evita el 80% de los problemas que generan tickets de soporte en los primeros días. Esto significa clientes más satisfechos, menos llamadas de emergencia, y una experiencia de marca impecable desde el día uno. El Hunter debe comunicar que la visita técnica es una inversión en tranquilidad.', '"La mayoría de los problemas que tienen los clientes de otros POS son por falta de validación técnica: internet lento, hardware incompatible, mala ubicación de equipos. Nosotros prevenimos eso antes de la instalación, para que no tengas sorpresas después. La visita técnica es tu garantía de que el sistema funcionará sin problemas desde el día uno."', NULL, NULL, NULL, 31);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'La Visita Técnica como Argumento de Cierre', 'El informe técnico resultante de la visita es una herramienta poderosa para el cierre. El Hunter lo usa para armar una cotización precisa con costos de hardware justificados. El informe es un documento con peso técnico que demuestra al cliente que la inversión es necesaria y que INVU es un socio confiable.', 'Un cliente duda sobre la inversión en hardware. El Hunter presenta el informe: "Nuestro especialista validó que tu operación necesita X hardware para funcionar de manera óptima. Te recomendamos esta inversión para garantizar continuidad. Sin esto, tu sistema podría tener fallas en horas pico. Con esto, operas sin interrupciones." El cliente, al ver el informe técnico, acepta la inversión.', NULL, NULL, NULL, 32);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'La Pregunta Clave – ¿Qué Tipo de Internet Tienen?', 'El Hunter debe preguntar en el discovery: "¿Qué tipo de conexión a internet tienen y qué velocidad contratada?" Fibra óptica (FTTH) es recomendada; coaxial (HFC) genera latencia inestable. Esta pregunta permite al Hunter anticipar problemas y preparar al cliente para posibles mejoras.', 'Un Hunter pregunta: "¿Qué tipo de internet tienen?" El cliente responde: "Coaxial de 100MB." El Hunter sabe que esto puede ser problemático. Dice: "El coaxial puede generar latencia en horas pico. Nuestro especialista lo evaluará en la visita técnica y te recomendará si necesitas migrar a fibra óptica para garantizar estabilidad." El cliente valora la transparencia.', NULL, NULL, NULL, 33);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'La Pregunta Clave – ¿Qué Hardware Utilizan Actualmente?', 'El Hunter debe preguntar: "¿Qué equipos y hardware utilizan actualmente (marcas, modelos, antigüedad)?" Esto incluye impresoras, tablets, computadoras, lectores, cajones de dinero. Saber esto permite al Hunter dimensionar la reutilización de hardware y preparar al cliente para posibles reemplazos.', 'Un Hunter pregunta: "¿Qué tablets usan?" El cliente responde: "Tablets de 5 años." El Hunter dice: "Entiendo. Nuestro especialista evaluará si aún son funcionales o si necesitan reemplazo. Si funcionan, las reutilizamos; si no, te recomendamos nuevas." El cliente se siente escuchado y confía en el proceso.', NULL, NULL, NULL, 34);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'La Pregunta Clave – ¿Tienen un Área de Cocina Separada?', 'El Hunter debe preguntar: "¿Tienen un área de cocina o producción separada? ¿Dónde se ubican las estaciones de venta?" Esto permite planificar la ubicación estratégica de los equipos (POS, KDS, impresoras de comandas) y garantizar la eficiencia operativa.', 'Un Hunter pregunta y descubre que la cocina está a 15 metros de la caja. Dice: "Perfecto. Nuestro especialista evaluará la mejor ubicación para la impresora de comandas y la pantalla KDS. Así los pedidos llegan rápido a cocina y tu personal no pierde tiempo." El cliente valora que el Hunter esté pensando en su flujo de trabajo.', NULL, NULL, NULL, 35);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'La Pregunta Clave – ¿Manejan Delivery o Apps?', 'El Hunter debe preguntar: "¿Manejan delivery o integraciones con apps como Rappi o PedidosYa?" Si el cliente tiene alta demanda de delivery, necesita un enlace de internet más estable y un router con respaldo 4G. Esta pregunta permite al Hunter anticipar necesidades de hardware crítico.', 'El cliente responde: "Sí, movemos S/10,000 al mes por delivery." El Hunter dice: "Excelente. Entonces tu internet debe ser muy estable y tener respaldo. Nuestro especialista evaluará tu red y te recomendará un router 4G de respaldo para que nunca pierdas una venta de delivery." El cliente ve el valor inmediato.', NULL, NULL, NULL, 36);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'El Framework Gravity Aplicado a Hardware – Diagnóstico', 'El Hunter debe hacer las preguntas de diagnóstico sobre hardware y red durante el discovery o la demo. No debe esperar a la visita técnica para descubrir problemas. El diagnóstico temprano permite preparar al cliente y al especialista técnico, y posiciona al Hunter como un consultor proactivo.', 'En el discovery, el Hunter pregunta sobre internet, hardware y distribución. Al identificar que el cliente tiene coaxial y tablets viejas, dice: "Nuestro especialista evaluará esto en la visita técnica. Te anticipo que podríamos recomendar migrar a fibra óptica y renovar algunas tablets. Pero no te preocupes, evaluaremos todo y te daremos un informe con prioridades."', NULL, NULL, NULL, 37);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'El Framework Gravity Aplicado a Hardware – Educación', 'El Hunter educa al cliente sobre la importancia de la visita técnica: "Nuestro especialista va a evaluar tu red, hardware y distribución para asegurarse de que la implementación sea 100% exitosa. Esto es parte de nuestro modelo llave en mano. No te dejamos solo con el software; validamos tu infraestructura para que no tengas sorpresas." La educación es clave para que el cliente vea la visita como un valor agregado.', 'Un cliente dice: "No sé si necesito la visita técnica." El Hunter responde: "Es parte de nuestro servicio. No queremos que instales el sistema y descubras que tu internet es lento o que tu hardware no es compatible. Preferimos validar todo antes, para que desde el día uno estés operando sin interrupciones."', NULL, NULL, NULL, 38);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'El Framework Gravity Aplicado a Hardware – Comparación', 'El Hunter compara con la competencia: "Otros sistemas te entregan el software y tú te las arreglas para que funcione. Si tu internet es lento o tu hardware no es compatible, te das cuenta después de la instalación y pierdes días resolviendo problemas. INVU valida todo antes, para que desde el día uno estés operando sin interrupciones." Esta comparación posiciona a INVU como el socio confiable.', 'El cliente dice: "Mi amigo tiene otro POS y no necesitó visita técnica." El Hunter responde: "Y probablemente tuvo problemas los primeros días. Nosotros preferimos prevenir. La visita técnica es lo que nos diferencia: validamos tu infraestructura antes de instalar, para que no tengas sorpresas."', NULL, NULL, NULL, 39);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'El Framework Gravity Aplicado a Hardware – Construcción de Valor', 'El Hunter construye valor mostrando los beneficios de la visita técnica: "Con esta evaluación, aseguramos que tu sistema funcione sin caídas, que tu hardware sea el adecuado, que tu personal pueda operar sin frustraciones, y que puedas seguir vendiendo incluso si el internet falla gracias al respaldo 4G. No es un gasto, es una inversión en la continuidad de tu negocio." El valor es la tranquilidad operativa.', '"Imagina que un viernes a las 8pm, en pleno horario pico, el internet se cae. Con el respaldo 4G, tu sistema sigue operando. Esa es la tranquilidad que te da la visita técnica. No perderás una venta por un corte de internet."', NULL, NULL, NULL, 40);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'El Framework Gravity Aplicado a Hardware – Cierre', 'El Hunter cierra la agenda de la visita técnica: "¿Qué día te acomoda que nuestro especialista vaya a tu local para hacer la evaluación? Es sin costo para ti y te daremos un informe con recomendaciones personalizadas." El cierre es asegurar la visita, que es el paso previo a la cotización y el cierre final.', 'Después de presentar el valor de la visita técnica, el Hunter dice: "¿Qué te parece si agendamos la visita para el próximo martes? El especialista irá a tu local, hará la evaluación, y te dará un informe. Sin compromiso. Después decides qué hardware renovar." El cliente acepta y el Hunter agenda la visita.', NULL, NULL, NULL, 41);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'El Manejo de la Objeción "No Quiero Invertir en Hardware Nuevo"', 'El cliente que dice "no quiero invertir en hardware nuevo" está preocupado por el costo. El Hunter debe validar, educar sobre la reutilización de hardware, comparar con la competencia (que obliga a comprar todo nuevo), y construir valor mostrando que la inversión se paga sola con la eficiencia ganada.', '"Entiendo. Por eso hacemos la visita técnica: para evaluar qué se puede reutilizar y qué necesita reemplazo. Nuestro especialista te dirá con honestidad qué equipos aún sirven y cuáles te están generando pérdidas de tiempo y dinero. No te vamos a vender algo que no necesites. Y la inversión en hardware nuevo se paga sola con la eficiencia que ganas."', NULL, NULL, NULL, 42);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'El Manejo de la Objeción "¿Por qué Tengo que Pagar por la Visita Técnica?"', 'El cliente que pregunta por el costo de la visita técnica debe ser informado de que es gratuita y parte del modelo llave en mano. El Hunter debe comunicar que la visita técnica es una inversión de INVU para asegurar el éxito del cliente, no un costo adicional.', '"La visita técnica es gratuita para ti. Es parte de nuestro modelo llave en mano. No te cobramos por la evaluación, la incluimos en el setup. Queremos asegurarnos de que tu implementación sea 100% exitosa desde el día uno. No es un gasto, es una inversión nuestra en tu éxito."', NULL, NULL, NULL, 43);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', 'Los Niveles de Dominio en Hardware y Visita Técnica', 'El Hunter pasa por 4 niveles en el manejo de hardware y visita técnica: Básico (conoce el proceso pero no lo ejecuta proactivamente), Medio (ejecuta la visita como parte del proceso), Alto (usa la visita como herramienta de valor y upselling), y Gravedad Cero (integra la visita en su estrategia de consultoría, anticipa necesidades, y convierte cada visita en una oportunidad de venta adicional, incrementando el setup facturado en un 40% o más).', 'Básico: Sabe que existe la visita técnica, pero no la menciona hasta que el cliente pregunta.  
